-- Catálogo oficial inicial (gerado a partir de data/catalog.json). Pode rodar de novo: não duplica.
insert into comandos (id, categoria, nome, resumo, comando, parametro, rotulo_parametro, exemplo, atalhos, escolha, pede_confirmacao, texto_confirmacao, gera_arquivo, oficial) values
  ('listar', 'Pacotes', 'Listar pacotes', 'Lista os pacotes do aparelho. Escolha o filtro: só os instalados pelo usuário, só os de sistema, todos, ou todos com o caminho do APK.', 'adb -s {s} shell pm list packages {p}', 'text', 'Filtro', '-3', '[{"rotulo": "Do usuário", "valor": "-3"}, {"rotulo": "Do sistema", "valor": "-s"}, {"rotulo": "Todos", "valor": "-a"}, {"rotulo": "Com caminho", "valor": "-f"}]'::jsonb, '{"pergunta": "Quais pacotes?", "opcao_outro": null}'::jsonb, false, null, false, true),
  ('buscar', 'Pacotes', 'Localizar pacote pelo nome', 'Procura o pacote digitando só um pedaço do nome. Inclui apps do sistema.', 'adb -s {s} shell "pm list packages | grep {p}"', 'text', 'Parte do nome do pacote', 'mobiltec', '[{"rotulo": "mobiltec", "valor": "mobiltec"}, {"rotulo": "datamob", "valor": "datamob"}, {"rotulo": "emergencymode", "valor": "emergencymode"}]'::jsonb, null, false, null, false, true),
  ('path', 'Pacotes', 'Localizar caminho do APK', 'Mostra onde o APK do app está no aparelho, inclusive apps de sistema em /system/priv-app.', 'adb -s {s} shell pm path {p}', 'pkg', null, null, null, null, false, null, false, true),
  ('extrair', 'Apps', 'Extrair APK', 'Localiza o APK (de usuário ou de sistema) e copia pra pasta de saída com o nome do pacote.', 'adb -s {s} shell pm path {p}
adb -s {s} pull <caminho> "{d}\{p}.apk"', 'pkg', null, null, null, null, false, null, true, true),
  ('instalar', 'Apps', 'Instalar APK', 'Instala um APK do computador. Se o app já existir, atualiza mantendo os dados.', 'adb -s {s} install -r "{p}"', 'apk', null, null, null, null, false, null, false, true),
  ('downgrade', 'Apps', 'Instalar APK forçado (downgrade)', 'Instala mesmo sendo versão mais antiga ou build de teste. Mantém os dados do app.', 'adb -s {s} install -t -r -d "{p}"', 'apk', null, null, null, null, false, null, false, true),
  ('desinstalar', 'Apps', 'Remover app', 'Desinstala o app do aparelho, junto com os dados dele.', 'adb -s {s} uninstall {p}', 'pkg', null, null, null, null, true, 'desinstalar {p}', false, true),
  ('removersis', 'Apps', 'Remover app de sistema', 'Tira um app de sistema do usuário sem root (some do aparelho, mas dá pra trazer de volta). Bom pra bloatware.', 'adb -s {s} shell pm uninstall -k --user 0 {p}', 'text', 'Pacote de sistema', 'com.sec.android.emergencymode.service', '[{"rotulo": "Modo emergência (Samsung)", "valor": "com.sec.android.emergencymode.service"}]'::jsonb, null, true, 'remover {p} do usuário', false, true),
  ('reativar', 'Apps', 'Reativar app de sistema removido', 'Traz de volta um app de sistema removido com o comando acima.', 'adb -s {s} shell cmd package install-existing {p}', 'text', 'Pacote de sistema', 'com.sec.android.emergencymode.service', '[{"rotulo": "Modo emergência (Samsung)", "valor": "com.sec.android.emergencymode.service"}]'::jsonb, null, false, null, false, true),
  ('limpar', 'Apps', 'Limpar dados do app', 'Apaga dados, cache e login do app, deixando como recém-instalado.', 'adb -s {s} shell pm clear {p}', 'pkg', null, null, null, null, true, 'apagar todos os dados de {p}', false, true),
  ('parar', 'Apps', 'Forçar parada', 'Fecha o app à força. Útil quando ele trava.', 'adb -s {s} shell am force-stop {p}', 'pkg', null, null, null, null, false, null, false, true),
  ('versao', 'Pacotes', 'Ver versão do app', 'Versão instalada e quando o app foi instalado/atualizado.', 'adb -s {s} shell "dumpsys package {p} | grep -E ''versionName|versionCode|firstInstallTime|lastUpdateTime''"', 'pkg', null, null, null, null, false, null, false, true),
  ('permissoes', 'Pacotes', 'Ver permissões do app', 'Permissões em tempo de execução e se estão concedidas.', 'adb -s {s} shell "dumpsys package {p} | grep granted="', 'pkg', null, null, null, null, false, null, false, true),
  ('rodando', 'Pacotes', 'Ver se o app está rodando', 'Mostra se o processo do app está ativo agora, com o PID.', 'adb -s {s} shell "ps -A | grep {p}"', 'pkg', null, null, null, null, false, null, false, true),
  ('grant', 'Pacotes', 'Conceder permissão', 'Dá uma permissão ao app sem precisar tocar na tela. Escreva o pacote, um espaço e a permissão.', 'adb -s {s} shell pm grant {p}', 'text', 'Pacote e permissão', 'pacote android.permission.X', '[{"rotulo": "Localização", "valor": "br.com.mobiltec.c4m.android.agent android.permission.ACCESS_FINE_LOCATION"}, {"rotulo": "Telefone", "valor": "br.com.mobiltec.c4m.android.agent android.permission.READ_PHONE_STATE"}, {"rotulo": "Notificações", "valor": "br.com.mobiltec.c4m.android.agent android.permission.POST_NOTIFICATIONS"}]'::jsonb, null, false, null, false, true),
  ('resetperm', 'Pacotes', 'Resetar permissões do app', 'Volta todas as permissões do app pro estado inicial, como se nunca tivessem sido pedidas.', 'adb -s {s} shell pm reset-permissions -p {p}', 'pkg', null, null, null, null, true, 'resetar todas as permissões de {p}', false, true),
  ('verowner', 'Aparelho', 'Ver Device Owner atual', 'Mostra qual app é o dono do dispositivo hoje.', 'adb -s {s} shell "dumpsys device_policy | grep -A2 ''Device Owner''"', null, null, null, null, null, false, null, false, true),
  ('foco', 'Telas', 'Ver app em foco', 'Mostra qual app e tela estão na frente agora (mCurrentFocus).', 'adb -s {s} shell "dumpsys window windows | grep -E ''mCurrentFocus''"', null, null, null, null, null, false, null, false, true),
  ('topo', 'Telas', 'Ver activity no topo', 'Nome completo da activity aberta, pra usar depois no “Abrir tela”.', 'adb -s {s} shell "dumpsys activity top | grep ACTIVITY"', null, null, null, null, null, false, null, false, true),
  ('topold', 'Telas', 'Ver top-activity (Android antigo)', 'Alternativa pra aparelhos antigos, onde o comando acima não traz resultado.', 'adb -s {s} shell "dumpsys activity | grep top-activity"', null, null, null, null, null, false, null, false, true),
  ('abrirtela', 'Telas', 'Abrir tela específica', 'Abre uma activity direto pelo nome. Use os atalhos ou cole o que saiu em “Ver activity no topo”.', 'adb -s {s} shell am start -n {p}', 'text', 'Activity (pacote/classe)', 'pacote/classe', '[{"rotulo": "Chrome", "valor": "com.android.chrome/com.google.android.apps.chrome.Main"}, {"rotulo": "Launcher Samsung", "valor": "com.sec.android.app.launcher/com.android.launcher2.Launcher"}, {"rotulo": "Configurações", "valor": "com.android.settings/com.android.settings.Settings"}, {"rotulo": "Meus Arquivos Samsung", "valor": "com.sec.android.app.myfiles/com.sec.android.app.myfiles.MainActivity"}]'::jsonb, null, false, null, false, true),
  ('url', 'Telas', 'Abrir link no aparelho', 'Abre um endereço no navegador padrão do aparelho.', 'adb -s {s} shell am start -a android.intent.action.VIEW -d "{p}"', 'text', 'Endereço', 'https://www.google.com', null, null, false, null, false, true),
  ('botao', 'Controle', 'Apertar botão', 'Simula um botão físico ou de navegação: Home, Voltar, Recentes, Power, Volume.', 'adb -s {s} shell input keyevent {p}', 'text', 'Código da tecla', '3', '[{"rotulo": "Home", "valor": "3"}, {"rotulo": "Voltar", "valor": "4"}, {"rotulo": "Recentes", "valor": "187"}, {"rotulo": "Power (tela)", "valor": "26"}, {"rotulo": "Volume +", "valor": "24"}, {"rotulo": "Volume −", "valor": "25"}, {"rotulo": "Enter", "valor": "66"}]'::jsonb, '{"pergunta": "Qual botão?", "opcao_outro": "Outra tecla…"}'::jsonb, false, null, false, true),
  ('digitar', 'Controle', 'Digitar texto no aparelho', 'Escreve o texto no campo aberto no aparelho. Útil pra senha de Wi-Fi, códigos e URLs longas.', 'adb -s {s} shell input text "{p}"', 'text', 'Texto', 'texto a digitar', null, null, false, null, false, true),
  ('tela', 'Controle', 'Ver resolução e densidade', 'Mostra a resolução e a densidade da tela, úteis pra checar layout de quiosque.', 'adb -s {s} shell wm size
adb -s {s} shell wm density', null, null, null, null, null, false, null, false, true),
  ('info', 'Aparelho', 'Informações do aparelho', 'Modelo, fabricante, versão do Android, patch de segurança e build.', 'adb -s {s} shell "getprop | grep -E ''ro.product.model|ro.product.manufacturer|ro.build.version.release|ro.build.version.security_patch|ro.build.display.id''"', null, null, null, null, null, false, null, false, true),
  ('bateria', 'Aparelho', 'Estado da bateria', 'Nível, temperatura, se está carregando e saúde da bateria.', 'adb -s {s} shell dumpsys battery', null, null, null, null, null, false, null, false, true),
  ('armazenamento', 'Aparelho', 'Espaço de armazenamento', 'Quanto espaço está usado e livre na memória interna.', 'adb -s {s} shell df -h /data', null, null, null, null, null, false, null, false, true),
  ('hora', 'Aparelho', 'Data e hora do aparelho', 'Hora errada costuma quebrar sincronização e certificados.', 'adb -s {s} shell date', null, null, null, null, null, false, null, false, true),
  ('reiniciar', 'Aparelho', 'Reiniciar aparelho', 'Reinicia o aparelho normalmente, ou direto no modo recovery ou bootloader.', 'adb -s {s} reboot {p}', 'text', 'Modo', null, '[{"rotulo": "Normal", "valor": ""}, {"rotulo": "Recovery", "valor": "recovery"}, {"rotulo": "Bootloader", "valor": "bootloader"}]'::jsonb, '{"pergunta": "Reiniciar em qual modo?", "opcao_outro": null}'::jsonb, true, 'reiniciar o aparelho', false, true),
  ('print', 'Captura', 'Screenshot pra área de transferência', 'Tira print da tela e já deixa copiado. Também salva na pasta de saída.', 'adb -s {s} exec-out screencap -p > "{d}\screenshot_2026-11-24_14-32-05.png"', null, null, null, null, null, false, null, true, true),
  ('gravar', 'Captura', 'Gravar tela', 'Grava até 3 minutos da tela. Clique de novo pra parar e salvar.', 'adb -s {s} shell screenrecord /sdcard/gravacao.mp4', null, null, null, null, null, false, null, true, true),
  ('loglimpar', 'Logs', 'Limpar log do aparelho', 'Zera o log antes de reproduzir o problema, pra o log salvo só ter o que interessa.', 'adb -s {s} logcat -c', null, null, null, null, null, false, null, false, true),
  ('logcontinuo', 'Logs', 'Gravar log contínuo em arquivo', 'Fica gravando o logcat em .txt até você clicar em Parar. Nome do arquivo com a data, no padrão log20261124.', 'adb -s {s} logcat -v threadtime > "{d}\log20261124_1432.txt"', null, null, null, null, null, false, null, true, true),
  ('logsalvar', 'Logs', 'Salvar log atual em arquivo', 'Puxa o log que já está no aparelho e salva na hora, sem ficar gravando.', 'adb -s {s} logcat -d -v threadtime > "{d}\log20261124_1432.txt"', null, null, null, null, null, false, null, true, true),
  ('logcat', 'Logs', 'Logcat de um app', 'Mostra só o log do app escolhido, sem o ruído do resto do sistema.', 'adb -s {s} logcat -v threadtime --pid=<pid de {p}>', 'pkg', null, null, null, null, false, null, false, true),
  ('bugreport', 'Logs', 'Extrair bugreport', 'Relatório completo do Android, salvo na pasta de saída. Demora de 1 a 3 minutos.', 'adb -s {s} bugreport "{d}\bugreport_2026-11-24_14-32.zip"', null, null, null, null, null, false, null, true, true),
  ('diag', 'Logs', 'Coletar diagnóstico completo', 'Junta log, propriedades, apps, bateria e screenshot num zip só.', 'adb -s {s} logcat -d -v threadtime > "{d}\logcat.txt"
adb -s {s} shell getprop > "{d}\props.txt"
adb -s {s} shell pm list packages > "{d}\apps.txt"
adb -s {s} shell dumpsys battery > "{d}\bateria.txt"
adb -s {s} exec-out screencap -p > "{d}\tela.png"', null, null, null, null, null, false, null, true, true),
  ('enviar', 'Arquivos', 'Enviar arquivo pro aparelho', 'Copia um arquivo (ex.: um APK) do computador pra raiz do armazenamento do aparelho.', 'adb -s {s} push "{p}" /sdcard/', 'file', null, null, null, null, false, null, false, true),
  ('baixar', 'Arquivos', 'Baixar arquivo do aparelho', 'Copia um arquivo do aparelho pra pasta de saída.', 'adb -s {s} pull "{p}" "{d}"', 'path', null, null, null, null, false, null, true, true),
  ('listarpasta', 'Arquivos', 'Listar pasta do aparelho', 'Mostra os arquivos de uma pasta do aparelho, com tamanho e data.', 'adb -s {s} shell ls -la {p}', 'path', null, '/sdcard/Download/', '[{"rotulo": "Download", "valor": "/sdcard/Download/"}, {"rotulo": "Raiz", "valor": "/sdcard/"}, {"rotulo": "Fotos", "valor": "/sdcard/DCIM/Camera/"}]'::jsonb, null, false, null, false, true),
  ('conexao', 'Conexão', 'Diagnosticar conexão', 'Verifica se o adb enxerga os aparelhos e se a depuração USB está autorizada.', 'adb devices -l', null, null, null, null, null, false, null, false, true),
  ('servidor', 'Conexão', 'Reiniciar o adb', 'Derruba e sobe de novo o servidor do adb. Resolve a maioria dos “aparelho não aparece” e “offline”.', 'adb kill-server
adb start-server', null, null, null, null, null, false, null, false, true),
  ('shell', 'Conexão', 'Abrir shell do aparelho', 'Abre uma janela de terminal já dentro do aparelho selecionado, pra digitar comandos livres.', 'adb -s {s} shell', null, null, null, null, null, false, null, false, true),
  ('wifi', 'Conexão', 'Conectar via Wi-Fi', 'Libera o adb pela rede, pra trabalhar sem cabo (aparelho e PC na mesma rede).', 'adb -s {s} tcpip 5555
adb connect 192.168.0.143:5555', null, null, null, null, null, false, null, false, true),
  ('usb', 'Conexão', 'Voltar pra conexão USB', 'Desliga o adb pela rede e volta a usar só o cabo.', 'adb -s {s} usb', null, null, null, null, null, false, null, false, true)
on conflict (id) do nothing;
